def poly_mask_uv(verts, n=16):
 m=np.zeros((n,n),bool)
 # even-odd ray crossing, points on boundary excluded
 for r in range(n):
  for c in range(n):
   x=c-r; y=r
   inside=False
   for i in range(len(verts)):
    x1,y1=verts[i]; x2,y2=verts[(i+1)%len(verts)]
    # boundary strict exclude
    cross=(x2-x1)*(y-y1)-(y2-y1)*(x-x1)
    if abs(cross)<1e-9 and min(x1,x2)<=x<=max(x1,x2) and min(y1,y2)<=y<=max(y1,y2):
     inside=False; break
    if (y1>y)!=(y2>y):
     xcross=x1+(y-y1)*(x2-x1)/(y2-y1)
     if x<xcross: inside=not inside
   m[r,c]=inside
 return m
